-- (가)
SELECT COUNT(*) FROM LINE
 WHERE 요금제코드 NOT IN (SELECT 요금제코드 FROM EXCL);

-- (나)
SELECT COUNT(*) FROM LINE L
 WHERE NOT EXISTS (SELECT 1 FROM EXCL E
                    WHERE E.요금제코드 = L.요금제코드);

-- (다)
SELECT AVG(할인율) FROM LINE;

-- (가)
SELECT * FROM PLAN
 WHERE 기본료 > ALL (SELECT 기본료 FROM PLAN WHERE 망구분 = 'LTE');
-- (나)
SELECT * FROM PLAN
 WHERE 기본료 > ANY (SELECT 기본료 FROM PLAN WHERE 망구분 = '5G');
-- (다)
SELECT * FROM PLAN
 WHERE 기본료 < ALL (SELECT 기본료 FROM PLAN WHERE 망구분 = '6G');

-- (가)
SELECT 고객번호 FROM A UNION     SELECT 고객번호 FROM B;
-- (나)
SELECT 고객번호 FROM A INTERSECT SELECT 고객번호 FROM B;
-- (다)
SELECT 고객번호 FROM A MINUS     SELECT 고객번호 FROM B;

SELECT 망구분, 요금제, SUM(금액) AS 합계
  FROM BILL2
 GROUP BY GROUPING SETS (망구분, ROLLUP(망구분, 요금제));

-- (가)
SELECT 회선번호, 청구금액 FROM BILL
 ORDER BY 청구금액 DESC
 FETCH FIRST 2 ROWS WITH TIES;
-- (나)
SELECT * FROM (SELECT 회선번호, 청구금액 FROM BILL ORDER BY 청구금액 DESC)
 WHERE ROWNUM <= 2;
-- (다)
SELECT * FROM BILL WHERE ROWNUM > 1;

